// SI-assisted: skeleton, weights, science_field and cost_map generated by Claude Code (SI tool); `hazard_mask` written by a team member.
//! 懲罰成本圖（B6）。
//!
//! 概念：每一格有一個「走過去的代價」，A* 會找總代價最小的路線。
//! - 硬限制：危險格的代價 = ∞，A* 絕對不會走。
//! - 軟懲罰：可以走但比較「貴」，A* 會盡量繞開。
//!
//! 計畫中的公式（docs/PLAN.md「核心演算法規格」）：
//! ```text
//! cost = 1 + W_slope·(slope/slope_max)² + W_rough·rough_norm
//!          + W_buf·exp(-d/σ)  − W_sci·science      （下限 min_cost）
//! hazard 格 → ∞
//! ```

use crate::grid::Grid;
use crate::world::World;
use rayon::prelude::*;
use serde::{Deserialize, Serialize};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Deserialize, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Mode {
    Safe,
    Balanced,
    Science,
}

impl Mode {
    pub const ALL: [Mode; 3] = [Mode::Safe, Mode::Balanced, Mode::Science];
}

/// 一種模式的權重。數值由團隊決定，並在簡報中說明理由。
#[derive(Clone, Copy, Debug)]
pub struct CostWeights {
    /// 坡度懲罰權重
    pub w_slope: f32,
    /// 粗糙度懲罰權重
    pub w_rough: f32,
    /// 危險區緩衝懲罰權重
    pub w_buf: f32,
    /// 緩衝距離尺度 σ（公尺）：離危險區 σ 公尺時，緩衝懲罰剩 e⁻¹ ≈ 37%
    pub sigma_m: f32,
    /// 科學獎勵權重（越大越願意靠近科學目標）
    pub w_sci: f32,
    /// 成本下限（必須 > 0，A* 的啟發函數靠它保證最佳解）
    pub min_cost: f32,
}

impl CostWeights {
    /// 三種模式的權重（假設值，可調）。
    /// - safe：陡坡、粗糙地面和危險區附近都很貴，σ = 20 m（跌倒滑行的保守距離），幾乎不為科學繞路。
    /// - science：願意走較陡、較近危險區的捷徑（σ = 8 m），並被科學目標吸引。
    /// - min_cost > 0：A* 的啟發函數 = 距離 × min_cost，才能保證最佳解。
    pub fn for_mode(mode: Mode) -> Self {
        match mode {
            Mode::Safe => Self { w_slope: 4.0, w_rough: 2.0, w_buf: 6.0, sigma_m: 20.0, w_sci: 0.2, min_cost: 0.1 },
            Mode::Balanced => Self { w_slope: 2.5, w_rough: 1.2, w_buf: 4.5, sigma_m: 16.0, w_sci: 0.5, min_cost: 0.1 },
            Mode::Science => Self { w_slope: 1.2, w_rough: 0.4, w_buf: 1.2, sigma_m: 8.0, w_sci: 0.9, min_cost: 0.1 },
        }
    }
}

/// 危險區門檻。由團隊決定並說明依據。
#[derive(Clone, Copy, Debug)]
pub struct HazardThresholds {
    /// 超過此坡度視為不可通行（度）
    pub slope_max_deg: f32,
    /// 超過此粗糙度視為岩塊、不可通行（公尺）
    pub rough_max_m: f32,
}

impl Default for HazardThresholds {
    /// 25°：Apollo 登月車的設計爬坡上限，作為穿太空衣步行的硬上限；
    /// 0.3 m：合成地形實測，岩塊區 p99 ≈ 0.5、boxwork 最大 ≈ 0.21 → 岩塊被擋、boxwork 可通行。
    fn default() -> Self {
        Self { slope_max_deg: 25.0, rough_max_m: 0.3 }
    }
}

/// 危險遮罩（true = 不可通行）：坡度或粗糙度任一超過門檻。（團隊成員撰寫）
pub fn hazard_mask(slope: &Grid<f32>, rough: &Grid<f32>, th: HazardThresholds) -> Grid<bool> {
    let data: Vec<bool> = slope
        .data
        .iter()
        .zip(&rough.data)          // 同時走坡度和粗糙度兩張圖
        .map(|(&s, &r)| s > th.slope_max_deg || r > th.rough_max_m)       // s = 這格的坡度，r = 這格的粗糙度
        .collect();
    Grid::from_vec(slope.w, slope.h, slope.cell_m, data)
}


/// 科學價值場（0–1）：每個目標貢獻 `science · exp(-d²/(2r²))`，重疊時取最大值
/// （取 max 而非相加，避免多個目標疊加後把成本扣到過低）。只處理目標周圍 3r 內的格子。
pub fn science_field(world: &World, radius_m: f32) -> Grid<f32> {
    let dem = &world.dem;
    let mut g = Grid::new(dem.w, dem.h, dem.cell_m, 0.0f32);
    let reach = 3.0 * radius_m;
    for t in &world.targets {
        let i0 = ((t.x - reach) / dem.cell_m).floor().max(0.0) as usize;
        let i1 = (((t.x + reach) / dem.cell_m).ceil() as usize).min(dem.w.saturating_sub(1));
        let j0 = ((t.y - reach) / dem.cell_m).floor().max(0.0) as usize;
        let j1 = (((t.y + reach) / dem.cell_m).ceil() as usize).min(dem.h.saturating_sub(1));
        for j in j0..=j1 {
            for i in i0..=i1 {
                let (x, y) = dem.center(i, j);
                let d2 = (x - t.x).powi(2) + (y - t.y).powi(2);
                let v = t.science * (-d2 / (2.0 * radius_m * radius_m)).exp();
                let k = g.idx(i, j);
                if v > g.data[k] {
                    g.data[k] = v;
                }
            }
        }
    }
    g
}

/// 計算成本圖需要的所有輸入圖層（皆與 DEM 同尺寸）。
pub struct CostInputs<'a> {
    pub slope: &'a Grid<f32>,
    pub rough: &'a Grid<f32>,
    pub hazard: &'a Grid<bool>,
    /// 到最近危險格的距離（公尺），用 `edt::distance_to(hazard)` 算
    pub clearance: &'a Grid<f32>,
    /// 科學價值 0–1
    pub science: &'a Grid<f32>,
    pub slope_max_deg: f32,
    /// 粗糙度正規化用的尺度（公尺）
    pub rough_scale_m: f32,
}

/// 依公式計算每格成本；hazard 格為 `f32::INFINITY`。
pub fn cost_map(inp: &CostInputs, w: &CostWeights) -> Grid<f32> {
    let n = inp.slope.data.len();
    let data: Vec<f32> = (0..n)
        .into_par_iter()
        .map(|k| {
            if inp.hazard.data[k] {
                return f32::INFINITY;
            }
            let s = inp.slope.data[k] / inp.slope_max_deg;
            let r = inp.rough.data[k] / inp.rough_scale_m;
            let buf = (-inp.clearance.data[k] / w.sigma_m).exp();
            let c = 1.0 + w.w_slope * s * s + w.w_rough * r + w.w_buf * buf - w.w_sci * inp.science.data[k];
            c.max(w.min_cost)
        })
        .collect();
    Grid::from_vec(inp.slope.w, inp.slope.h, inp.slope.cell_m, data)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::edt::distance_to;

    /// 測試用的小場景：平地，中間一格 30° 陡坡。
    fn tiny() -> (Grid<f32>, Grid<f32>) {
        let mut slope = Grid::new(21, 21, 1.0, 0.0f32);
        slope.set(10, 10, 30.0);
        let rough = Grid::new(21, 21, 1.0, 0.0f32);
        (slope, rough)
    }

    #[test]
    fn steep_cell_is_hazard() {
        let (slope, rough) = tiny();
        let hz = hazard_mask(&slope, &rough, HazardThresholds { slope_max_deg: 25.0, rough_max_m: 1.0 });
        assert!(hz.get(10, 10));
        assert!(!hz.get(0, 0));
    }

    #[test]
    fn hazard_is_infinite_and_cost_decreases_with_distance() {
        let (slope, rough) = tiny();
        let hz = hazard_mask(&slope, &rough, HazardThresholds { slope_max_deg: 25.0, rough_max_m: 1.0 });
        let clr = distance_to(&hz);
        let sci = Grid::new(21, 21, 1.0, 0.0f32);
        let inp = CostInputs {
            slope: &slope,
            rough: &rough,
            hazard: &hz,
            clearance: &clr,
            science: &sci,
            slope_max_deg: 25.0,
            rough_scale_m: 1.0,
        };
        let c = cost_map(&inp, &CostWeights::for_mode(Mode::Safe));
        assert!(c.get(10, 10).is_infinite());
        // 沿著一列往外走，成本應該單調不增（離危險越遠越便宜）
        for i in 11..20 {
            assert!(c.get(i + 1, 10) <= c.get(i, 10), "cost should not increase away from hazard at i={i}");
        }
    }

    #[test]
    fn modes_are_ordered_sensibly() {
        let (s, b, sc) = (CostWeights::for_mode(Mode::Safe), CostWeights::for_mode(Mode::Balanced), CostWeights::for_mode(Mode::Science));
        assert!(s.w_buf >= b.w_buf && b.w_buf >= sc.w_buf, "safe 應該最重視緩衝");
        assert!(sc.w_sci >= b.w_sci && b.w_sci >= s.w_sci, "science 應該最重視科學");
        for w in [s, b, sc] {
            assert!(w.min_cost > 0.0, "min_cost 必須 > 0");
            assert!(w.sigma_m > 0.0);
        }
    }

    #[test]
    fn science_field_peaks_at_target() {
        let w = crate::synth::generate(&crate::synth::SynthSpec { w: 128, h: 128, cell_m: 8.0, seed: 3 });
        let f = science_field(&w, 60.0);
        let t = &w.targets[0];
        let (i, j) = w.dem.to_cell(t.x, t.y).unwrap();
        assert!(f.get(i, j) > 0.9 * t.science);
        assert!(f.get(0, 0) < 1e-3);
        assert!(f.data.iter().all(|&v| (0.0..=1.0).contains(&v)));
    }
}
